-- A payment received from a client on a date, allocated to one or more of its invoices.
CREATE TABLE payment (
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    client_id    BIGINT         NOT NULL REFERENCES client (id),
    amount       DECIMAL(19, 2) NOT NULL,
    payment_date DATE           NOT NULL
);

-- How much of a payment goes to which invoice.
CREATE TABLE payment_allocation (
    payment_id BIGINT         NOT NULL REFERENCES payment (id) ON DELETE CASCADE,
    invoice_id BIGINT         NOT NULL REFERENCES invoice (id) ON DELETE CASCADE,
    amount     DECIMAL(19, 2) NOT NULL
);
-- Whether the payment has been reversed (a bounced cheque): it then no longer counts anywhere.
ALTER TABLE payment ADD COLUMN reversed BOOLEAN DEFAULT FALSE NOT NULL;
-- The day a part of a payment was applied to its invoice, when later than the payment itself (credit
-- held on the client's account used when an invoice is sent); null means the payment's own date.
ALTER TABLE payment_allocation ADD COLUMN applied_date DATE;
  // is a draft or already paid (anything paid beyond what is due is held as credit), or the date is after today or before
  // the issue date, or the reference is mistyped (400) or another invoice's (409). Answers the invoice with its payments and new status.
  recordPayment(invoiceId: number, payment: NewPayment): Observable<InvoiceDetail> {
    return this.http.post<InvoiceDetail>(`/api/invoices/${invoiceId}/payments`, payment);
  }

  // Records one payment spread over several of the client's invoices; refused (409) unless the parts
  // add up to the payment and each goes to a sent invoice of the client, no more than it has due.
  // With no parts it goes to the invoices whose references are quoted (comma separated), earliest due
  // date first, refused when one is mistyped (400) or not the client's; what they do not owe is held as credit.
  // Answers the client's invoices with their new statuses.
  recordSplitPayment(clientId: number, payment: NewSplitPayment): Observable<InvoiceSummary[]> {
    return this.http.post<InvoiceSummary[]>(`/api/clients/${clientId}/payments`, payment);
  }

  // Records a deposit: the whole amount held on the client's account as credit, applied to no invoice
  // until one of the client's invoices is sent; refused (409) when dated after today. Answers the
  // client's invoices.
  recordDeposit(clientId: number, deposit: { amount: string; date: string }): Observable<InvoiceSummary[]> {
    return this.http.post<InvoiceSummary[]>(`/api/clients/${clientId}/deposits`, deposit);
  }

  // Reverses a payment (a bounced cheque) on every invoice it was applied to; refused (409) when it
  // has already been reversed. Answers the opened invoice with its payments and new status.
  reversePayment(invoiceId: number, paymentId: number): Observable<InvoiceDetail> {
    return this.http.post<InvoiceDetail>(`/api/invoices/${invoiceId}/payments/${paymentId}/reverse`, null);
  }
}
